import { __ } from "@wordpress/i18n";
import visibleIcon from "./visible.svg";
import hideIcon from "./hide.svg";

import { StyleComp } from "./StyleInput";
import { useCallback, useEffect, useRef, useState } from "@wordpress/element";
import { useMergeRefs } from "@wordpress/compose";
import { StyleSheetManager } from "styled-components";
import { useDispatch } from "@wordpress/data";

import LabelBox from "../LabelBox";
import {
	useElementBackgroundColor,
	useIsIframeMobile,
	ShadowStyle,
	ShadowElm,
	TypographyControls,
	useTargetBlocks,
	fetchZipToAddress,
} from "itmar-block-packages";

import {
	PanelBody,
	PanelRow,
	ToggleControl,
	RadioControl,
	TextControl,
	RangeControl,
	SelectControl,
	__experimentalNumberControl as NumberControl,
	Notice,
	__experimentalUnitControl as UnitControl,
	__experimentalBoxControl as BoxControl,
	__experimentalBorderBoxControl as BorderBoxControl,
} from "@wordpress/components";
import {
	useBlockProps,
	InspectorControls,
	__experimentalPanelColorGradientSettings as PanelColorGradientSettings,
	__experimentalBorderRadiusControl as BorderRadiusControl,
} from "@wordpress/block-editor";

import "./editor.scss";
import { toStyleRecord } from "../front-common";
import type {
	ShadowStyleResult,
	TargetTextBlock,
	TextCtrlAttributes,
	TextCtrlEditProps,
	TextCtrlInputType,
	TextCtrlPosition,
	RadiusValue,
	ZipAddress,
} from "./types";

type ShadowState = Parameters<typeof ShadowElm>[0];

//スペースのリセットバリュー
type BoxControlValue = Partial<
	Record<"top" | "right" | "bottom" | "left", string | undefined>
>;

const padding_resetValues = {
	top: "10px",
	left: "10px",
	right: "10px",
	bottom: "10px",
};

//ボーダーのリセットバリュー
const border_resetValues = {
	top: "0px",
	left: "0px",
	right: "0px",
	bottom: "0px",
};

const units = [
	{ value: "px", label: "px" },
	{ value: "em", label: "em" },
	{ value: "rem", label: "rem" },
];

const inputTypes: TextCtrlInputType[] = [
	"text",
	"number",
	"email",
	"pass",
	"zip",
	"textarea",
];

const isTextCtrlInputType = (value: string): value is TextCtrlInputType =>
	inputTypes.includes(value as TextCtrlInputType);

const mergeBoxValues = (
	current: TextCtrlPosition["margin_input"],
	value: BoxControlValue,
): TextCtrlPosition["margin_input"] => ({
	...current,
	...Object.fromEntries(
		Object.entries(value).filter(
			(entry): entry is ["top" | "right" | "bottom" | "left", string] =>
				typeof entry[1] === "string",
		),
	),
});

const normalizeRadiusValue = (value: unknown): RadiusValue => {
	if (typeof value === "string") return { value };
	if (value && typeof value === "object") return value as RadiusValue;
	return {};
};

const asNumber = (value: number | undefined, fallback: number): number =>
	typeof value === "number" ? value : fallback;

export default function Edit(props: TextCtrlEditProps) {
	const { attributes, setAttributes, clientId } = props;

	const {
		inputName,
		inputValue,
		placeFolder,
		inputType,
		numberOption,
		addressInput,
		required,
		focusColor,
		bgColor,
		font_style_input,
		bgColor_input,
		bgGradient_input,
		textColor_input,
		radius_input,
		border_input,
		default_pos,
		mobile_pos,
		labelContent,
		shadow_element,
		is_shadow,
		className,
	} = attributes;

	//モバイルの判定
	const isMobile = useIsIframeMobile();

	//ブロックの参照
	const blockRef = useRef<HTMLDivElement | null>(null);
	const [styleSheetTarget, setStyleSheetTarget] = useState<HTMLElement | null>(
		null,
	);
	const ownerDocumentRef = useCallback((node: HTMLDivElement | null) => {
		setStyleSheetTarget(node?.ownerDocument.head ?? null);
	}, []);
	const mergedBlockRef = useMergeRefs([blockRef, ownerDocumentRef]);
	const blockProps = useBlockProps({
		ref: mergedBlockRef,
		style: { backgroundColor: bgColor },
	});

	//背景色の取得
	const baseColor = useElementBackgroundColor(blockRef, blockProps.style);

	//背景色変更によるシャドー属性の書き換え
	useEffect(() => {
		if (baseColor) {
			setAttributes({
				shadow_element: { ...shadow_element, baseColor: baseColor },
			});
			const new_shadow = ShadowElm({
				...(shadow_element as unknown as ShadowState),
				baseColor: baseColor,
			});
			if (new_shadow) {
				setAttributes({ shadow_result: toStyleRecord(new_shadow.style) });
			}
		}
	}, [baseColor]);

	//必須項目の表示
	const dispLabel = required.flg
		? `${labelContent}(${required.display})`
		: labelContent;

	//親コンポーネントからのラベル幅の指定があればそれを採用して記録する
	const label_width = String(props.context["itmar/label_width"] || "auto");
	useEffect(() => {
		setAttributes({ labelWidth: label_width });
	}, [label_width]);

	//入力値の確保
	const [stateValue, setInputValue] = useState<string>(String(inputValue ?? ""));
	useEffect(() => {
		setInputValue(String(inputValue ?? "")); // ← 属性が変わったら useState も追従
	}, [inputValue]);

	//テキストエリアの高さ設定
	const [height, setHeight] = useState("auto");
	const textAreaRef = useRef<HTMLTextAreaElement | null>(null);

	useEffect(() => {
		if (textAreaRef.current) {
			setHeight(`${textAreaRef.current.scrollHeight}px`);
		}
	}, [className]);

	//パスワードの表示トグル
	const [showPassword, setShowPassword] = useState(false);

	//住所の入力対象となるブロックの配列
	const targetblocks = useTargetBlocks(
		clientId,
		"itmar/design-text-ctrl",
	) as TargetTextBlock[];
	const targetArray = targetblocks.map((block) => ({
		label: String(block.attributes.labelContent ?? ""),
		value: String(block.attributes.inputName ?? ""),
	}));
	//住所の代入対象のブロック
	const targetBlock =
		targetblocks.find((block) => block.attributes.inputName === addressInput) ??
		null;
	const { updateBlockAttributes } = useDispatch("core/block-editor");
	const updateInputValue = (value: string | number) => {
		const nextValue = String(value);
		setInputValue(nextValue);
		setAttributes({ inputValue: nextValue });
	};

	return (
		<>
			<InspectorControls group="settings">
				<PanelBody
					title={__("Input element information setting", "block-collections")}
					initialOpen={true}
					className="title_design_ctrl"
				>
					<PanelRow>
						<TextControl
							label={__("ID and Name attribute name", "block-collections")}
							value={inputName}
							onChange={(newVal: string) => setAttributes({ inputName: newVal })}
						/>
					</PanelRow>
					<PanelRow>
						<TextControl
							label={__("PlaceHolder", "block-collections")}
							value={placeFolder}
							onChange={(newVal: string) => setAttributes({ placeFolder: newVal })}
						/>
					</PanelRow>
					<PanelRow className="itmar_weight_row">
						<RadioControl
							selected={inputType}
							label={__("Kind of Input Element", "block-collections")}
							options={[
								{ label: "TEXT", value: "text" },
								{ label: "NUMBER", value: "number" },
								{ label: "E-MAIL", value: "email" },
								{ label: "PASSWORD", value: "pass" },
								{ label: "ZIP", value: "zip" },
								{ label: "AREA", value: "textarea" },
							]}
								onChange={(changeOption: string) => {
									if (isTextCtrlInputType(changeOption)) {
										setAttributes({ inputType: changeOption });
									}
								}}
						/>
					</PanelRow>
					{inputType === "number" && (
						<PanelBody
							title={__("Number Options", "block-collections")}
							initialOpen={true}
						>
							<RangeControl
								label={__("Minimum value (min)", "block-collections")}
								value={numberOption.min}
								onChange={(min?: number) =>
									setAttributes({
										numberOption: {
											...numberOption,
											min: asNumber(min, numberOption.min),
										},
									})
								}
								min={-100}
								max={numberOption.max}
								help={__("Set the minimum allowed value.", "block-collections")}
							/>
							<RangeControl
								label={__("Maximum value (max)", "block-collections")}
								value={numberOption.max}
								onChange={(max?: number) =>
									setAttributes({
										numberOption: {
											...numberOption,
											max: asNumber(max, numberOption.max),
										},
									})
								}
								min={numberOption.min}
								max={100}
								help={__("Set the maximum allowed value.", "block-collections")}
							/>
							<NumberControl
								label={__("Step", "block-collections")}
								value={numberOption.step}
								min={1}
								max={Math.max(numberOption.max - numberOption.min, 1)}
								onChange={(step?: string | number) =>
									setAttributes({
										numberOption: { ...numberOption, step: Number(step) },
									})
								}
								help={__(
									"Change the increment/decrement step for the value.",
									"block-collections",
								)}
							/>
							{numberOption.min > numberOption.max && (
								<Notice status="error" isDismissible={false}>
									{__(
										"The minimum value (min) should not be greater than the maximum value (max).",
										"block-collections",
									)}
								</Notice>
							)}
						</PanelBody>
					)}
					{inputType === "zip" && (
						<PanelRow>
							<SelectControl
								label={__("Address text box", "block-collections")}
								value={addressInput}
								options={targetArray}
								onChange={(newName: string) => {
									setAttributes({ addressInput: newName });
								}}
							/>
						</PanelRow>
					)}
				</PanelBody>
			</InspectorControls>
			<InspectorControls group="styles">
				<PanelBody
					title={__("Global settings", "block-collections")}
					initialOpen={false}
					className="title_design_ctrl"
				>
					<PanelColorGradientSettings
						title={__("Background Color Setting", "block-collections")}
						settings={[
							{
								colorValue: bgColor,
								label: __("Choose Background color", "block-collections"),
								onColorChange: (newValue?: string) =>
									setAttributes({ bgColor: newValue ?? "" }),
							},
						]}
					/>
					<PanelColorGradientSettings
						title={__("Focus Color Setting", "block-collections")}
						settings={[
							{
								colorValue: focusColor,
								label: __("Choose Focus color", "block-collections"),
								onColorChange: (newValue?: string) =>
									setAttributes({ focusColor: newValue }),
							},
						]}
					/>
					<BoxControl
						label={
							!isMobile
								? __("Margin settings(desk top)", "block-collections")
								: __("Margin settings(mobile)", "block-collections")
						}
						values={
							!isMobile ? default_pos.margin_input : mobile_pos.margin_input
						}
						onChange={(value: BoxControlValue) => {
							if (!isMobile) {
								setAttributes({
									default_pos: {
										...default_pos,
										margin_input: mergeBoxValues(
											default_pos.margin_input,
											value,
										),
									},
								});
							} else {
								setAttributes({
									mobile_pos: {
										...mobile_pos,
										margin_input: mergeBoxValues(mobile_pos.margin_input, value),
									},
								});
							}
						}}
						units={units} // 許可する単位
						allowReset={true} // リセットの可否
						resetValues={padding_resetValues} // リセット時の値
					/>
					<BoxControl
						label={
							!isMobile
								? __("Padding settings(desk top)", "block-collections")
								: __("Padding settings(mobile)", "block-collections")
						}
						values={
							!isMobile ? default_pos.padding_input : mobile_pos.padding_input
						}
						onChange={(value: BoxControlValue) => {
							if (!isMobile) {
								setAttributes({
									default_pos: {
										...default_pos,
										padding_input: mergeBoxValues(
											default_pos.padding_input,
											value,
										),
									},
								});
							} else {
								setAttributes({
									mobile_pos: {
										...mobile_pos,
										padding_input: mergeBoxValues(
											mobile_pos.padding_input,
											value,
										),
									},
								});
							}
						}}
						units={units} // 許可する単位
						allowReset={true} // リセットの可否
						resetValues={padding_resetValues} // リセット時の値
					/>

					<ToggleControl
						label={__("Is Shadow", "block-collections")}
						checked={is_shadow}
						onChange={(newVal: boolean) => {
							setAttributes({ is_shadow: newVal });
						}}
					/>
					{is_shadow && (
						<ShadowStyle
							shadowStyle={shadow_element as unknown as ShadowState}
							onChange={(newStyle: ShadowStyleResult, newState: ShadowState) => {
								setAttributes({ shadow_result: toStyleRecord(newStyle.style) });
								setAttributes({ shadow_element: { ...newState } });
							}}
						/>
					)}
				</PanelBody>
				<PanelBody
					title={__("Input Box style settings", "block-collections")}
					initialOpen={false}
					className="title_design_ctrl"
				>
					<TypographyControls
						title={__("Typography", "block-collections")}
						fontStyle={font_style_input}
						onChange={(newStyle: TextCtrlAttributes["font_style_input"]) => {
							setAttributes({ font_style_input: newStyle });
						}}
						isMobile={isMobile}
						initialOpen={false}
					/>
					<UnitControl
						label={
							!isMobile
								? __("Free Width(desk top)", "block-collections")
								: __("Free Width(mobile)", "block-collections")
						}
						dragDirection="e"
						onChange={(value?: string) => {
							if (!isMobile) {
								setAttributes({
									default_pos: { ...default_pos, free_width: value ?? "" },
								});
							} else {
								setAttributes({
									mobile_pos: { ...mobile_pos, free_width: value ?? "" },
								});
							}
						}}
						value={
							!isMobile
								? default_pos.free_width ?? default_pos.freeWidth ?? ""
								: mobile_pos.free_width ?? mobile_pos.freeWidth ?? ""
						}
					/>
					<RangeControl
						value={Number(
							!isMobile
								? default_pos.inputLineHeight
								: mobile_pos.inputLineHeight,
						)}
						label={
							!isMobile
								? __("Line Height(desk top)", "block-collections")
								: __("Line Height(mobile)", "block-collections")
						}
						max={3}
						min={1}
						step={0.1}
						onChange={(value?: number) => {
							if (!isMobile) {
								setAttributes({
									default_pos: {
										...default_pos,
										inputLineHeight: asNumber(value, Number(default_pos.inputLineHeight)),
									},
								});
							} else {
								setAttributes({
									mobile_pos: {
										...mobile_pos,
										inputLineHeight: asNumber(value, Number(mobile_pos.inputLineHeight)),
									},
								});
							}
						}}
						withInputField={true}
					/>
					<PanelColorGradientSettings
						title={__("Color Settings", "block-collections")}
						settings={[
							{
								colorValue: textColor_input,
								label: __("Choose Text color", "block-collections"),
								onColorChange: (newValue?: string) =>
									setAttributes({ textColor_input: newValue ?? "" }),
							},
							{
								colorValue: bgColor_input,
								gradientValue: bgGradient_input,

								label: __("Choose Background color", "block-collections"),
								onColorChange: (newValue?: string) =>
									setAttributes({ bgColor_input: newValue }),
								onGradientChange: (newValue?: string) =>
									setAttributes({ bgGradient_input: newValue }),
							},
						]}
					/>
					<PanelBody
						title={__("Border Settings", "block-collections")}
						initialOpen={false}
						className="border_design_ctrl"
					>
						<BorderBoxControl
							onChange={(newValue: Record<string, unknown> | undefined) =>
								setAttributes({ border_input: newValue ?? {} })
							}
							value={border_input}
							allowReset={true} // リセットの可否
							resetValues={border_resetValues} // リセット時の値
						/>
						<BorderRadiusControl
							values={radius_input}
							onChange={(newBrVal: unknown) =>
								setAttributes({
									radius_input: normalizeRadiusValue(newBrVal),
								})
							}
						/>
					</PanelBody>
				</PanelBody>
			</InspectorControls>

			<div {...blockProps}>
				<StyleSheetManager target={styleSheetTarget ?? undefined}>
					<StyleComp attributes={attributes}>
					{inputType === "text" && (
						<input
							type="text"
							name={inputName}
							placeholder={
								className?.includes("is-style-line") ? dispLabel : placeFolder
							}
							className={`contact_text ${stateValue ? "" : "empty"}`}
							value={stateValue}
							onChange={(event) => {
								const newValue = event.target.value;
								updateInputValue(newValue);
							}}
						/>
					)}
					{inputType === "email" && (
						<input
							type="email"
							placeholder={
								className?.includes("is-style-line") ? dispLabel : placeFolder
							}
							className={`contact_text ${stateValue ? "" : "empty"}`}
							value={stateValue}
							onChange={(event) => {
								const newValue = event.target.value;
								updateInputValue(newValue);
							}}
						/>
					)}

					{inputType === "pass" && (
						<div className="password-wrapper">
							<input
								type={showPassword ? "text" : "password"}
								placeholder={
									className?.includes("is-style-line") ? dispLabel : placeFolder
								}
								className={`contact_text ${stateValue ? "" : "empty"}`}
								value={stateValue}
								onChange={(event) => {
									const newValue = event.target.value;
									updateInputValue(newValue);
								}}
							/>
							<button
								type="button"
								className="toggle-password-button"
								onClick={() => setShowPassword(!showPassword)}
								aria-label={
									showPassword ? "パスワードを非表示" : "パスワードを表示"
								}
							>
								<img
									src={showPassword ? visibleIcon : hideIcon}
									alt=""
									aria-hidden="true"
								/>
							</button>
						</div>
					)}
					{inputType === "zip" && (
						<div className="zip-search-wrapper">
							<input
								type="text"
								value={stateValue}
								placeholder={`${__("example", "block-collections")}) 1234567`}
								className={`contact_text ${stateValue ? "" : "empty"}`}
								onChange={(event) => {
									const newValue = event.target.value;
									updateInputValue(newValue);
								}}
							/>
							<button
								type="button"
								onClick={async () => {
									const address_obj = (await fetchZipToAddress(
										stateValue,
									)) as ZipAddress | null;
									if (!address_obj) return;

									const fullAddress = `${address_obj.address1 ?? ""}${
										address_obj.address2 ?? ""
									}${address_obj.address3 ?? ""}`;
									if (targetBlock) {
										updateBlockAttributes(
											targetBlock.clientId,
											{
												inputValue: fullAddress,
											},
										);
									} else {
										alert(
											__(
												"The block to enter the address cannot be found.",
												"block-collections",
											),
										);
									}
								}}
								className="zip-search-button"
							>
								{__("Address Search", "block-collections")}
							</button>
						</div>
					)}
					{inputType === "number" && (
						<div className="number-input-wrapper">
							<button
								type="button"
								onClick={() => {
									const min = Number(numberOption.min);
									const max = Number(numberOption.max);
									let newValue =
										(parseInt(stateValue, 10) || 0) -
										Number(numberOption.step || 1);
									if (newValue < min) newValue = min;
									if (newValue > max) newValue = max;
									updateInputValue(newValue);
								}}
							>
								-
							</button>
							<input
								type="number"
								name={inputName}
								min={numberOption.min}
								max={numberOption.max}
								step={numberOption.step}
								placeholder={
									className?.includes("is-style-line") ? dispLabel : ""
								}
								className={`contact_text ${stateValue ? "" : "empty"}`}
								value={stateValue}
								onChange={(event) => {
									const min = Number(numberOption.min);
									const max = Number(numberOption.max);
									let newValue = event.target.value;

									// 入力値が範囲内かどうかをチェック
									if (newValue === "") {
										updateInputValue("");
										return;
									}
									let numericValue = Number(newValue);
									if (isNaN(numericValue)) return;
									if (numericValue < min) numericValue = min;
									if (numericValue > max) numericValue = max;
									updateInputValue(numericValue);
								}}
							/>
							<button
								type="button"
								onClick={() => {
									const min = Number(numberOption.min);
									const max = Number(numberOption.max);
									let newValue =
										(parseInt(stateValue, 10) || 0) +
										Number(numberOption.step || 1);
									if (newValue > max) newValue = max;
									if (newValue < min) newValue = min;
									updateInputValue(newValue);
								}}
							>
								+
							</button>
						</div>
					)}
					{inputType === "textarea" && (
						<textarea
							ref={textAreaRef}
							style={{ height }}
							name={inputName}
							placeholder={
								className?.includes("is-style-line") ? dispLabel : placeFolder
							}
							className={`contact_text ${stateValue ? "" : "empty"}`}
							value={stateValue}
							onChange={(event) => {
								const newValue = event.target.value;
								const scrollHeight = event.target.scrollHeight;
								updateInputValue(newValue);
								setHeight(`${scrollHeight}px`);
							}}
						/>
					)}
					<LabelBox
						attributes={{ ...attributes, isMobile: isMobile }}
						onChange={(target: string, newVal: unknown) =>
							setAttributes({ [target]: newVal })
						}
					/>
					</StyleComp>
				</StyleSheetManager>
			</div>
		</>
	);
}
